package branchroom

import (
	"fmt"

	"gitea.dev/modules/setting"
	"gitea.dev/modules/util"
)

// ReceivePreReceiveHookTemplate renders the Branchroom-owned pre-receive delegate script.
// It stays inert until a "branchroom-pre-receive" hook command exists, and it embeds only
// server-owned values: session and bearer secrets are delivered out-of-band via hook environment.
func ReceivePreReceiveHookTemplate() string {
	return fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
exec %s hook --config=%s branchroom-pre-receive
`, setting.ScriptType, util.ShellEscape(setting.AppPath), util.ShellEscape(setting.CustomConf))
}
